MODEL_ID = "Qwen/Qwen3-VL-4B-Instruct"
MAX_NEW_TOKENS = 96
STRUCTURED_PROMPT = """You see a product image from an online store. The product title is: "{title}".
Describe ONLY visual information that is NOT already stated in the title.
Do not repeat or transcribe any words printed on the product, box, or cover.
Answer in at most 40 words as "key: value" pairs, choosing only relevant keys from:
color, material, shape/form factor, included items, art style, characters or scene shown, mood/theme, target audience cues, condition.
If the image clearly shows a different kind of product than the title, answer exactly: MISMATCH."""
GENERIC_PROMPT = "Describe this image in one sentence."
WORK_DIR = Path("/kaggle/working") if Path("/kaggle/working").is_dir() else Path.cwd()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def main() -> None:
    subprocess.run(
        [sys.executable, "-m", "pip", "install", "--no-cache-dir", "transformers==4.57.1", "pillow"],
        check=True,
    )
    import torch
    from PIL import Image
    from transformers import AutoProcessor, Qwen3VLForConditionalGeneration

    if not torch.cuda.is_available():
        raise RuntimeError("Qwen3-VL mismatch recheck requires the configured Kaggle GPU")
    items = json.loads(EMBEDDED_ITEMS_JSON)
    expected_ids = [4, 5, 10, 51, 65, 82, 83, 85, 88]
    if [int(item["n"]) for item in items] != expected_ids:
        raise ValueError(f"input manifest IDs drifted: {[item.get('n') for item in items]}")
    image_dir = WORK_DIR / "mismatch_recheck_images"
    image_dir.mkdir(parents=True, exist_ok=True)
    image_paths: dict[int, Path] = {}
    for item in items:
        image_name = item["image_file"]
        encoded = EMBEDDED_IMAGES_B85.get(image_name)
        if not encoded:
            raise FileNotFoundError(f"embedded image missing: {image_name}")
        image_bytes = base64.b85decode(encoded.encode("ascii"))
        if hashlib.sha256(image_bytes).hexdigest() != item["image_sha256"]:
            raise ValueError(f"embedded image SHA-256 mismatch for pilot row {item['n']}")
        image_path = image_dir / image_name
        image_path.write_bytes(image_bytes)
        image_paths[int(item["n"])] = image_path

    processor = AutoProcessor.from_pretrained(MODEL_ID)
    model = Qwen3VLForConditionalGeneration.from_pretrained(
        MODEL_ID,
        torch_dtype=torch.float16,
        attn_implementation="sdpa",
        device_map={"": 0},
    ).eval()
    devices = {str(parameter.device) for parameter in model.parameters()}
    if devices != {"cuda:0"}:
        raise RuntimeError(f"model was unexpectedly offloaded: {devices}")
    model_revision = getattr(model.config, "_commit_hash", None)
    if not model_revision:
        raise RuntimeError("model checkpoint revision was not resolved; refusing an unpinned result")

    def generate(prompt: str, image_path: Path | None) -> str:
        content = []
        if image_path is not None:
            with Image.open(image_path) as source:
                image = source.convert("RGB")
            image.thumbnail((768, 768))
            content.append({"type": "image", "image": image})
        content.append({"type": "text", "text": prompt})
        messages = [{"role": "user", "content": content}]
        inputs = processor.apply_chat_template(
            messages,
            tokenize=True,
            add_generation_prompt=True,
            return_dict=True,
            return_tensors="pt",
        ).to(model.device)
        with torch.inference_mode():
            generated = model.generate(**inputs, max_new_tokens=MAX_NEW_TOKENS, do_sample=False)
        continuation = generated[:, inputs["input_ids"].shape[1] :]
        text = processor.batch_decode(
            continuation,
            skip_special_tokens=True,
            clean_up_tokenization_spaces=False,
        )[0].strip()
        if not text:
            raise RuntimeError("Qwen3-VL returned an empty generation")
        return text

    smoke = generate(STRUCTURED_PROMPT.format(title=items[0]["title"]), image_paths[int(items[0]["n"])])
    print(f"smoke row={items[0]['n']}: {smoke}")
    output_path = WORK_DIR / "qwen3vl_mismatch_recheck.jsonl"
    metadata_path = WORK_DIR / "qwen3vl_mismatch_recheck_metadata.json"
    started = time.time()
    rows_written = 0
    with output_path.open("w", encoding="utf-8") as output:
        for item in items:
            item_id = int(item["n"])
            image_path = image_paths[item_id]
            structured = smoke if item_id == int(items[0]["n"]) else generate(STRUCTURED_PROMPT.format(title=item["title"]), image_path)
            generic = generate(GENERIC_PROMPT, image_path)
            record = {
                "n": item_id,
                "global_id": item["global_id"],
                "domain": item["domain"],
                "asin": item["asin"],
                "title": item["title"],
                "image_sha256": item["image_sha256"],
                "model": MODEL_ID,
                "model_revision": model_revision,
                "transformers_version": importlib.metadata.version("transformers"),
                "structured_rerun": structured,
                "generic_rerun": generic,
                "previous_structured": item["previous_structured"],
                "previous_generic": item["previous_generic"],
            }
            output.write(json.dumps(record, ensure_ascii=False) + "\n")
            output.flush()
            rows_written += 1
            print(f"completed {rows_written}/{len(items)}: pilot row {item_id}")
    if rows_written != len(expected_ids):
        raise RuntimeError(f"expected {len(expected_ids)} output rows, wrote {rows_written}")
    metadata = {
        "model": MODEL_ID,
        "model_revision": model_revision,
        "transformers_version": importlib.metadata.version("transformers"),
        "prompt_structured_sha256": hashlib.sha256(STRUCTURED_PROMPT.encode()).hexdigest(),
        "prompt_generic_sha256": hashlib.sha256(GENERIC_PROMPT.encode()).hexdigest(),
        "expected_row_ids": expected_ids,
        "output_row_count": rows_written,
        "output_sha256": sha256_file(output_path),
        "elapsed_seconds": round(time.time() - started, 2),
        "gpu": torch.cuda.get_device_name(0),
        "torch_version": torch.__version__,
        "cuda_version": torch.version.cuda,
    }
    metadata_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(metadata, indent=2))


if __name__ == "__main__":
    main()
